var turalyon = context.rulePiece;
if (!turalyon || turalyon.currentHp <= 0 || context.playerId !== turalyon.ownerPlayerId) return { success: false, message: '' };
if (['holy-smite', 'holy-heal', 'holy-charge'].indexOf(context.cardId) === -1) return { success: false, message: '' };
if (context.cancelled) return { success: true, message: turalyon.name + '放弃了本次圣铸进军' };
var selectedTargets = Array.isArray(context.selectedTargets) ? context.selectedTargets : [];
function destinationsFor(mover) { return flow.query.normalMoveTargets(mover.instanceId).filter(function(cell) { return canPlaceAdventurePiece(battle,mover,cell.x,cell.y); }).map(function(cell) { return { type: 'cell', x: cell.x, y: cell.y }; }); }
var allies = battle.pieces.filter(function(piece) { return piece.currentHp > 0 && canAffectAdventureTarget(battle,turalyon.ownerPlayerId,piece,turalyon) && arePlayersAllied(battle, piece.ownerPlayerId, turalyon.ownerPlayerId) && piece.x !== null && piece.y !== null; }).sort(function(a, b) { return a.instanceId < b.instanceId ? -1 : (a.instanceId > b.instanceId ? 1 : 0); });
if (selectedTargets.length === 0) {
  var moverCandidates = allies.filter(function(piece) { return destinationsFor(piece).length > 0; }).map(function(piece) { return { type: 'piece', pieceId: piece.instanceId }; });
  if (moverCandidates.length === 0) return { success: false, message: '' };
  return { success: false, needsTargetSelection: true, playerId: turalyon.ownerPlayerId, title: '圣铸进军：选择一名友方角色', targetType: 'piece', filter: 'ally', canCancel: true, resumeOnCancel: true, targetCandidates: moverCandidates };
}
var moverRef = selectedTargets[0];
var mover = moverRef && moverRef.type === 'piece' ? allies.find(function(piece) { return piece.instanceId === moverRef.pieceId; }) : null;
if (!mover) return { success: false, message: '选择的远征角色已失效' };
var destinations = destinationsFor(mover);
if (selectedTargets.length === 1) {
  return { success: false, needsTargetSelection: true, playerId: turalyon.ownerPlayerId, title: '圣铸进军：选择' + (mover.name || mover.templateId) + '的落点（点击高亮格）', targetType: 'grid', filter: 'all', canCancel: true, resumeOnCancel: true, targetCandidates: destinations };
}
var destinationRef = selectedTargets[1];
var destination = destinationRef && destinationRef.type === 'cell' ? destinations.find(function(cell) { return cell.x === destinationRef.x && cell.y === destinationRef.y; }) : null;
if (!destination) return { success: false, message: '远征移动的落点已失效' };
var result = flow.effects.freeMove(mover.instanceId, { x: destination.x, y: destination.y });
if (!result.success) return { success: true, message: '位移被阻挡，本次位移效果取消' };
return { success: true, message: mover.name + '完成圣铸进军，移动至(' + mover.x + ',' + mover.y + ')' };
